-- Add the slide-level structure used by the public Zertify Lesen flow.
-- The exercise text stays relational: exam -> section -> question -> option.
-- The JSON only describes the presentation order and shared content banks.

UPDATE reading_exam_sections
SET
  main_text = replace(replace(main_text, char(92) || 'r', ''), char(92) || 'n', char(10)),
  extra_data_json = CASE
    WHEN section_code = 'teil1' AND exam_id = 'zertify-b2-sport-01' THEN '{"source":"Zertify Lesen slide structure","slides":[{"id":"texte","label":"Texte","type":"texts","description":"Lesen Sie die fünf kurzen Mitteilungen."},{"id":"ueberschriften","label":"Überschriften","type":"headlines","description":"Ordnen Sie jeder Mitteilung die passende Überschrift zu."}],"titles":[{"code":"A","text":"Neue Haltestelle während der Bauarbeiten"},{"code":"B","text":"Stadtbad am Montag geschlossen"},{"code":"C","text":"Helfer für ein Vereinsfest gesucht"},{"code":"D","text":"Rückenkurs am Dienstagabend"},{"code":"E","text":"Fahrradhandschuhe im Fundbüro"}]}'
    WHEN section_code = 'teil1' THEN '{"source":"Zertify Lesen slide structure","slides":[{"id":"texte","label":"Texte","type":"texts","description":"Lesen Sie die fünf kurzen Mitteilungen."},{"id":"ueberschriften","label":"Überschriften","type":"headlines","description":"Ordnen Sie jeder Mitteilung die passende Überschrift zu."}],"titles":[{"code":"A","text":"Neue Haltestelle während der Bauarbeiten"},{"code":"B","text":"Bibliothek am Samstag geschlossen"},{"code":"C","text":"Helferinnen und Helfer für ein Fest gesucht"},{"code":"D","text":"Deutschkurs am Dienstagabend"},{"code":"E","text":"Rucksack im Fundbüro"}]}'
    WHEN section_code = 'teil2' THEN '{"source":"Zertify Lesen slide structure","slides":[{"id":"text","label":"Text","type":"text","description":"Lesen Sie den Text aufmerksam."},{"id":"fragen","label":"Fragen","type":"questions","description":"Wählen Sie bei jeder Aufgabe A, B oder C."}]}'
    WHEN section_code = 'teil3' AND exam_id = 'zertify-b2-sport-01' THEN '{"source":"Zertify Lesen slide structure","slides":[{"id":"situationen","label":"Situationen","type":"situations","description":"Lesen Sie die zehn Situationen."},{"id":"anzeigen","label":"Anzeigen","type":"ads","description":"Wählen Sie für jede Situation die passende Anzeige."}],"ads":[{"code":"A","text":"Bewegungszentrum Rückenfit: Rückenkurs am Dienstagabend"},{"code":"B","text":"RadWerk: Fahrradservice am Samstag"},{"code":"C","text":"YogaZeit: Abendkurs für Anfänger"},{"code":"D","text":"Schwimmclub Nord: Kindertraining"},{"code":"E","text":"Sportbörse: gebrauchte Kleidung"},{"code":"F","text":"LaufTreff: Morgenrunde für Anfänger"},{"code":"G","text":"PlanFit: individuelle Trainingsberatung"},{"code":"H","text":"WanderPlus: Ausrüstung für die Ferien"},{"code":"I","text":"Volleyball am Donnerstag"},{"code":"J","text":"Erste Hilfe Sport: Abendseminar"}]}'
    WHEN section_code = 'teil3' THEN '{"source":"Zertify Lesen slide structure","slides":[{"id":"situationen","label":"Situationen","type":"situations","description":"Lesen Sie die zehn Situationen."},{"id":"anzeigen","label":"Anzeigen","type":"ads","description":"Wählen Sie für jede Situation die passende Anzeige."}],"ads":[{"code":"A","text":"CityRad: Wochenendtarif, Abholung am Bahnhof"},{"code":"B","text":"Sprachzentrum Aktiv: Abendkurse"},{"code":"C","text":"TierZeit: liebevolle Ferienbetreuung"},{"code":"D","text":"Möbelbörse: Tische und Schränke aus zweiter Hand"},{"code":"E","text":"PC-Hilfe Zuhause: Reparatur und Beratung"},{"code":"F","text":"KochTreff International: gemeinsam kochen"},{"code":"G","text":"Notdienst-Apotheke am Rathaus, sonntags geöffnet"},{"code":"H","text":"Campus-Wohnen: Zimmer fünf Minuten von der Uni"},{"code":"I","text":"Jobtraining Kompakt: Bewerbung und Gespräch"},{"code":"J","text":"Schwimmbad Nord: werktags bis 22 Uhr"}]}'
    WHEN section_code = 'sprach1' THEN '{"source":"Zertify Lesen slide structure","slides":[{"id":"text","label":"Text","type":"text","description":"Lesen Sie die E-Mail aufmerksam."},{"id":"luecken","label":"Lücken","type":"gaps","description":"Wählen Sie das richtige Wort für jede Lücke."}],"wordBank":[{"code":"A","text":"für"},{"code":"B","text":"an"},{"code":"C","text":"über"},{"code":"D","text":"deshalb"},{"code":"E","text":"obwohl"},{"code":"F","text":"per"}]}'
    WHEN section_code = 'sprach2' THEN '{"source":"Zertify Lesen slide structure","slides":[{"id":"text","label":"Text","type":"text","description":"Lesen Sie die formelle Anfrage aufmerksam."},{"id":"luecken","label":"Lücken","type":"gaps","description":"Wählen Sie den Ausdruck, der am besten in den Text passt."}],"wordBank":[{"code":"A","text":"Sehr geehrte"},{"code":"B","text":"gesehen"},{"code":"C","text":"Dazu"},{"code":"D","text":"während"},{"code":"E","text":"wie viel"},{"code":"F","text":"möglich"},{"code":"G","text":"dankbar"}]}'
    ELSE extra_data_json
  END
WHERE exam_id IN ('pdf-b1-modelltest-01', 'zertify-b2-sport-01');
